#!ibl edition=2
$s1 = [limbs:browser]{op:"snapshot"}
$late = $s1.snapshot >> [table:filter]{where:($e)=>$e.role=="link" and $e.name=="지연만"}
[if:len($late)==0] { return {step:"no link after previous call hover", links:($s1.snapshot >> [table:filter]{where:($e)=>$e.role=="link"})} }
$c = [limbs:browser]{op:"click", ref:$late[0].ref}
$t = [limbs:browser]{op:"content", mode:"text"}
return {click:$c, url:$t.url, text:$t.text}
